import org.springframework.http.HttpRequest;
import org.springframework.http.client.ClientHttpRequestExecution;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.client.ClientHttpResponse;

import java.io.IOException;

class ValidatingClientHttpRequestInterceptorBad1 implements ClientHttpRequestInterceptor {
    @Override
    public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
        final ClientHttpResponse response = execution.execute(request, body);

        // should call ClientHttpResponse.close() and release resources if an exception is thrown
        someValidation(response);

        return response;
    }

    public static void someValidation(ClientHttpResponse response) {
        if (!response.getHeaders().containsKey("X-Some-Header")) {
            // Log error
            throw new RuntimeException("some error"); // bad
        }
    }
}

class ValidatingClientHttpRequestInterceptorBad2 implements ClientHttpRequestInterceptor {
    @Override
    public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
        final ClientHttpResponse response = execution.execute(request, body);

        // should call ClientHttpResponse.close() and release resources if an exception is thrown
        someValidation(response);

        return response;
    }

    public static void someValidation(ClientHttpResponse response) throws MyException {
        if (!response.getHeaders().containsKey("X-Some-Header")) {
            // log error
            throw new MyException("some error"); // bad
        }
    }
}
class MyException extends IOException {
    MyException(String message) { super(message); }
}

class ValidatingClientHttpRequestInterceptorGood implements ClientHttpRequestInterceptor {
    @Override
    public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
        final ClientHttpResponse response = execution.execute(request, body);

        // should call ClientHttpResponse.close() and release resources if an exception is thrown
        try {
            someValidation(response);
        } catch (MyException e) {
            // log error
            response.close(); // good
            throw new RuntimeException(e);
        }

        return response;
    }

    public static void someValidation(ClientHttpResponse response) throws MyException {
        if (!response.getHeaders().containsKey("X-Some-Header")) {
            throw new MyException("some error");
        }
    }
}

class ValidatingClientHttpRequestInterceptorGood2 implements ClientHttpRequestInterceptor {
    @Override
    public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
        final ClientHttpResponse response = execution.execute(request, body);

        // should call ClientHttpResponse.close() and release resources if an exception is thrown
        someValidation(response);

        return response;
    }

    public static void someValidation(ClientHttpResponse response) throws MyException {
        if (!response.getHeaders().containsKey("X-Some-Header")) {
            // log error
            response.close(); // good
            throw new MyException("some error");
        }
    }
}
